{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C32"],
      "claim": "Tofogliflozin, a close structural analogue in the same SGLT2 inhibitor class, showed 97.5% mean absolute oral bioavailability in healthy volunteers using an IV microdose comparator, strongly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Safinamide showed about 95% absolute oral bioavailability in healthy subjects after a single oral IR tablet dose in the fasted state, supporting high oral bioavailability for a small lipophilic oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Posaconazole tablet bioavailability in the fasted state was 56% in Western volunteers, above the 20% threshold and supportive of high F under fasting conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Lenvatinib absolute bioavailability is estimated at about 85% from human mass-balance data, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Drotaverine absolute bioavailability after oral 80 mg ranged from 24.5% to 91% with a mean of 58.2%, all above 20%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Amlodipine absolute bioavailability is estimated between 64% and 80% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Fasiglifam is characterized by rapid absorption and high oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Posaconazole oral suspension in pediatric patients had absolute bioavailability of 16% (8-27%), a low-F result, but this is formulation/population-specific and outweighed by high-F analogues.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C22"],
      "claim": "One report estimated sorafenib oral bioavailability at about 8.5%, but other human data indicate 38-49%; this low estimate is formulation/dose-specific and not representative of the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted high (F >= 20%) because the closest analogue tofogliflozin has 97.5% absolute oral bioavailability in humans and multiple other high-F oral drugs support high absorption; low-F outliers are formulation/population-specific and do not outweigh the strong high-F evidence.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself is included; the closest evidence is tofogliflozin, a close structural analogue.",
    "Fasted-state data for the query are not directly available; fasted-state evidence is inferred from analogues.",
    "Low-F records come from different formulations/populations (posaconazole suspension, sorafenib outlier) and may not reflect the query's solid oral fasted pharmacokinetics."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

